"""Random arrays and small divisors, weighted so adjacent multiples of n --
an additional way a hand-rolled iterator fix can still go wrong -- show
up often."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(2, 5)
    length = rng.randint(0, 15)
    values = []
    for _ in range(length):
        if rng.random() < 0.5:
            values.append(rng.randint(-10, 10) * n)  # a multiple of n
        else:
            values.append(rng.randint(-10, 10) * n + rng.randint(1, n - 1))
    lines = ["%d %d" % (len(values), n)] + [str(v) for v in values]
    return {"name": "%d values, removing multiples of %d #%d"
                    % (len(values), n, index),
            "stdin": " ".join(lines) + "\n"}
